<script setup>
import {useForm,Link} from '@inertiajs/vue3';import AppLayout from '../../Layouts/AppLayout.vue';const form=useForm({name:'',email:'',password:'',password_confirmation:''});const submit=()=>form.post('/register');
</script>
<template><AppLayout><div class="auth-wrap"><div class="auth-card"><h1>Buat akun baru</h1><p class="muted">Daftar untuk mulai berbelanja.</p><form @submit.prevent="submit"><div class="field"><label>Nama</label><input v-model="form.name" required><small style="color:#dc3545">{{form.errors.name}}</small></div><div class="field"><label>Email</label><input type="email" v-model="form.email" required><small style="color:#dc3545">{{form.errors.email}}</small></div><div class="field"><label>Password (minimal 8 karakter)</label><input type="password" v-model="form.password" required><small style="color:#dc3545">{{form.errors.password}}</small></div><div class="field"><label>Konfirmasi password</label><input type="password" v-model="form.password_confirmation" required></div><button class="btn" style="width:100%" :disabled="form.processing">Daftar</button></form><p class="muted">Sudah punya akun? <Link href="/login" style="color:#2457d6">Masuk</Link></p></div></div></AppLayout></template>
